import sys
from collections import deque

def solve():
    input = sys.stdin.read
    data = input().split()

    idx = 0
    n = int(data[idx]); idx += 1
    k = int(data[idx]); idx += 1

    main_courses = set()
    for _ in range(k):
        main_courses.add(int(data[idx])); idx += 1

    adj = [[] for _ in range(n + 1)]
    in_degree = [0] * (n + 1)
    dependencies = [[] for _ in range(n + 1)]

    for i in range(1, n + 1):
        t = int(data[idx]); idx += 1
        for _ in range(t):
            dep = int(data[idx]); idx += 1
            adj[dep].append(i)
            in_degree[i] += 1
            dependencies[i].append(dep)

    # We need to find all courses that are prerequisites for main courses
    # Start BFS/DFS from main courses backwards to find all required courses
    required = set(main_courses)
    queue = deque(main_courses)

    while queue:
        u = queue.popleft()
        for dep in dependencies[u]:
            if dep not in required:
                required.add(dep)
                queue.append(dep)

    # Now build a subgraph with only required nodes
    # Calculate in-degree within the subgraph
    sub_in_degree = {node: 0 for node in required}
    sub_adj = {node: [] for node in required}

    for u in required:
        for v in adj[u]:
            if v in required:
                sub_adj[u].append(v)
                sub_in_degree[v] += 1

    # Topological sort on the subgraph
    q = deque()
    for node in required:
        if sub_in_degree[node] == 0:
            q.append(node)

    result = []
    while q:
        u = q.popleft()
        result.append(u)
        for v in sub_adj[u]:
            sub_in_degree[v] -= 1
            if sub_in_degree[v] == 0:
                q.append(v)

    if len(result) != len(required):
        print(-1)
    else:
        print(len(result))
        print(*(result))

if __name__ == "__main__":
    solve()
